"""
hpe_brand -- identidade visual HPE Autos / HPE IA para o code interpreter.

FILOSOFIA
    Garante a MARCA e nada mais. NAO e um template fechado: o layout continua
    sendo sua escolha. Se nenhuma funcao pronta servir, use `slide_livre()`
    (slide em branco ja marcado) ou monte o slide na mao e chame
    `aplicar_marca(slide, prs)`.

DE ONDE VEM A MARCA (dois modos, automatico)
    1. MODO TEMPLATE (preferido) -- se `template-base.pptx` estiver disponivel,
       o deck e aberto a partir dele. O slideMaster do arquivo real da HPE ja
       carrega, em TODO slide: o fundo texturizado full-bleed, a faixa de logos
       dos parceiros (rodape esquerdo) e o badge INTEGRAR com as 5 bolinhas
       (rodape direito). Fidelidade pixel-perfect, zero trabalho.
    2. MODO FALLBACK -- sem o template, o deck e construido do zero e a marca e
       desenhada programaticamente (fundo claro + 5 bolinhas). Fica proximo,
       nao identico. Nada quebra.
    O badge "HPE IA" (canto superior direito) e sempre aplicado por slide, como
    no arquivo original -- ele vem embutido neste modulo em base64, entao nunca
    falta.

    Use `hb.diagnostico()` para saber em que modo voce esta.

USO MINIMO
    import sys; sys.path.insert(0, "/mnt/data")
    import hpe_brand as hb
    prs = hb.novo_deck()
    hb.slide_capa(prs, "Resultado Q3", "Diretoria Comercial")
    hb.slide_conteudo(prs, "Destaques", ["Receita +12%", "Churn -3pp"])
    hb.slide_grafico(prs, "Receita mensal", fig)
    hb.salvar(prs, "resultado.pptx")
"""

from __future__ import annotations

import base64
import os
import tempfile

# =====================================================================
# CONFIG -- extraido do template real (template-original.pptx, 21 slides).
# Troque em runtime com hb.configurar(...).
# =====================================================================

# --- cores ---
# Azul dos titulos: 55 de 57 ocorrencias de cor explicita nos 21 slides.
AZUL = "#1F4E79"
# Barra cinza lateral (1 ocorrencia, uso pontual).
CINZA_BARRA = "#C8C6BD"

# As 5 bolinhas da marca, amostradas pixel a pixel de faixa-secundaria.png.
VERMELHO = "#EB2F23"
LARANJA = "#F58634"
VERDE = "#A1CC38"
TEAL = "#009A93"
AZUL_MEDIO = "#1F60AC"

# Paleta de series para graficos = as 5 bolinhas, na ordem da faixa.
PALETA = [VERMELHO, LARANJA, VERDE, TEAL, AZUL_MEDIO]
# Estendida (para >5 series): as 5 bolinhas + o azul dos titulos + neutro.
PALETA_EXT = PALETA + [AZUL, "#8C9296"]

GRAFITE = "#3B3B3B"     # texto de corpo
CINZA = "#6E7679"       # texto auxiliar / notas
FUNDO_SOLIDO = "#F5F6F7"  # aproximacao do fundo texturizado (modo fallback)
BRANCO = "#FFFFFF"

# --- tipografia ---
# A fonte real dos slides e MMC / MMC OFFICE (proprietaria, NAO embutida no
# arquivo). Quem nao tem MMC instalada vera a substituicao do PowerPoint --
# no arquivo original a fonte pareada de fallback e Verdana.
FONTE = "MMC"
FONTE_TITULO = "MMC OFFICE"
FONTE_FALLBACK = "Verdana"
# O sandbox nao tem MMC nem Verdana; graficos saem em Liberation Sans.
FONTE_MPL = ["Verdana", "DejaVu Sans", "Liberation Sans", "sans-serif"]

# Escala de tamanhos observada: corpo/titulo 24pt, capa 45pt, destaque 70pt.
PT_TITULO = 24
PT_CAPA = 45
PT_CORPO = 20
PT_DESTAQUE = 70

# --- arquivos ---
# Onde procurar o template enxuto (239 KB). Primeiro match vence.
TEMPLATE_PATHS = [
    os.environ.get("HPE_TEMPLATE", ""),
    "/mnt/data/template-base.pptx",
    "/mnt/data/template-original.pptx",
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "template-base.pptx"),
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "assets", "template-base.pptx"),
]
# Badge HPE IA. Se o arquivo nao existir, cai no base64 embutido abaixo.
LOGO_PATH = os.environ.get("HPE_LOGO", "/mnt/data/logo-hpe-ia.png")

# Tamanho do slide em EMU, identico ao arquivo original (16:9).
EMU_LARGURA = 12192000
EMU_ALTURA = 6858000

# --- geometria real, em polegadas, medida nos 21 slides originais ---
GEO = {
    # badge HPE IA: identico nos 21 slides
    "logo": (12.07, 0.217, 0.939, 0.545),
    # header azul do slide de conteudo
    "titulo": (0.51, 0.22, 7.81, 0.5),
    "subtitulo": (0.51, 1.12, 7.81, 0.4),
    # titulo da capa
    "capa": (0.52, 2.14, 12.26, 0.86),
    # area util de conteudo: abaixo do header, acima da arte de rodape do master
    "corpo": (0.51, 1.62, 12.30, 5.05),
    # reguas horizontais que o master desenha (alinhe o conteudo entre elas)
    "regua_topo_y": 0.85,
    "regua_base_y": 6.69,
    # a arte do rodape do master comeca em y=6.83in -- nao invada
    "rodape_y": 6.69,
}

# Badge "HPE IA" 207x120 embutido para o modulo nunca depender de asset externo.
LOGO_B64 = ""


def configurar(**kw):
    """Sobrescreve qualquer constante de marca em runtime.

    Ex.: hb.configurar(FONTE="Verdana", AZUL="#1F4E79")
    """
    g = globals()
    for k, v in kw.items():
        if k.upper() in g:
            g[k.upper()] = v
        else:
            raise KeyError("configuracao desconhecida: %s" % k)
    g["PALETA_EXT"] = list(g["PALETA"]) + [g["AZUL"], "#8C9296"]
    return diagnostico()


def template_disponivel():
    """Caminho do template real, ou None (modo fallback)."""
    for p in TEMPLATE_PATHS:
        if p and os.path.isfile(p):
            return p
    return None


def diagnostico():
    """O que a marca conseguiu carregar. Chame se algo parecer errado."""
    tpl = template_disponivel()
    return {
        "modo": "template" if tpl else "fallback",
        "template": tpl,
        "logo": LOGO_PATH if os.path.isfile(LOGO_PATH) else "embutido (base64)",
        "fonte": FONTE,
        "fontes_mpl": registrar_fontes() or "nenhuma (fallback)",
        "paleta": list(PALETA),
        "aviso": None if tpl else
        "sem template-base.pptx: fundo texturizado e faixas do rodape sao "
        "aproximados. Anexe template-base.pptx ao agente para fidelidade total.",
    }


# =====================================================================
# Helpers internos
# =====================================================================

_LOGO_TMP = None


def _logo_arquivo():
    """Caminho de um PNG do badge. Usa o arquivo real, senao o embutido."""
    global _LOGO_TMP
    if LOGO_PATH and os.path.isfile(LOGO_PATH):
        return LOGO_PATH
    if _LOGO_TMP and os.path.isfile(_LOGO_TMP):
        return _LOGO_TMP
    if not LOGO_B64 or LOGO_B64.startswith("__"):
        return None
    try:
        _LOGO_TMP = os.path.join(tempfile.gettempdir(), "hpe-ia-badge.png")
        with open(_LOGO_TMP, "wb") as fh:
            fh.write(base64.b64decode(LOGO_B64))
        return _LOGO_TMP
    except Exception:
        return None


def _rgb(hexcor):
    from pptx.dml.color import RGBColor
    return RGBColor.from_string(str(hexcor).lstrip("#").upper())


def _in(v):
    from pptx.util import Inches
    return Inches(v)


# =====================================================================
# MATPLOTLIB
# =====================================================================

def cores(n=None):
    """N cores da marca para series de grafico (as 5 bolinhas, depois extras)."""
    base = PALETA_EXT
    if n is None:
        return list(PALETA)
    return [base[i % len(base)] for i in range(n)]


_FONTES_REGISTRADAS = None


def registrar_fontes():
    """Registra as fontes MMC no matplotlib, se os arquivos estiverem presentes.

    Para pptx/docx/xlsx basta o NOME da fonte -- o Office resolve na maquina de
    quem abre. Ja o matplotlib rasteriza o texto do grafico aqui dentro, entao
    sem os arquivos ele cai em Liberation Sans e o grafico sai com tipografia
    diferente do resto do slide. Anexe a pasta `fonts/` junto do modulo para
    fechar essa diferenca.

    Devolve a lista de familias efetivamente registradas.
    """
    global _FONTES_REGISTRADAS
    if _FONTES_REGISTRADAS is not None:
        return _FONTES_REGISTRADAS

    familias = []
    try:
        import glob
        from matplotlib import font_manager
        padroes = []
        for base in (".", "fonts", "/mnt/data", "/mnt/data/fonts", os.path.dirname(__file__)):
            padroes += [os.path.join(base, "MMC*.otf"), os.path.join(base, "MMC*.ttf")]
        vistos = set()
        for padrao in padroes:
            for arq in sorted(glob.glob(padrao)):
                real = os.path.realpath(arq)
                if real in vistos:
                    continue
                vistos.add(real)
                try:
                    font_manager.fontManager.addfont(real)
                    familias.append(font_manager.FontProperties(fname=real).get_name())
                except Exception:
                    pass
    except Exception:
        pass

    _FONTES_REGISTRADAS = sorted(set(familias))
    return _FONTES_REGISTRADAS


def estilo_grafico():
    """Aplica a identidade da HPE aos rcParams do matplotlib; devolve `plt`.

    Chame uma vez antes de plotar. Cuida de cor, fonte e bordas -- o tipo de
    grafico e a leitura dos dados continuam sendo sua escolha.
    """
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from cycler import cycler

    # Fontes reais primeiro; o fallback continua valendo se nao houver arquivo.
    registradas = registrar_fontes()
    preferidas = registradas + [f for f in FONTE_MPL if f not in registradas]

    plt.rcParams.update({
        "figure.figsize": (10.5, 5.0),
        "figure.dpi": 150,
        "figure.facecolor": "none",
        "savefig.transparent": True,   # deixa o fundo texturizado aparecer
        "axes.facecolor": "none",
        "axes.prop_cycle": cycler(color=PALETA_EXT),
        "axes.edgecolor": CINZA,
        "axes.labelcolor": GRAFITE,
        "axes.titlecolor": AZUL,
        "axes.titlesize": 15,
        "axes.titleweight": "bold",
        "axes.titlelocation": "left",
        "axes.spines.top": False,
        "axes.spines.right": False,
        "axes.grid": True,
        "grid.color": "#D8DCDF",
        "grid.linewidth": 0.8,
        "font.family": "sans-serif",
        "font.sans-serif": preferidas,
        "text.color": GRAFITE,
        "xtick.color": CINZA,
        "ytick.color": CINZA,
        "legend.frameon": False,
        "savefig.bbox": "tight",
    })
    return plt


def _fig_para_png(fig, dpi=150):
    path = tempfile.mktemp(suffix=".png")
    fig.savefig(path, dpi=dpi, bbox_inches="tight", transparent=True)
    return path


def _df_para_fig(df, kind=None):
    plt = estilo_grafico()
    fig, ax = plt.subplots()
    try:
        n_num = len(df.select_dtypes(include="number").columns)
    except Exception:
        n_num = 1
    kind = kind or ("line" if len(df) > 12 else "bar")
    df.plot(kind=kind, ax=ax, color=cores(max(n_num, 1)), legend=n_num > 1)
    fig.tight_layout()
    return fig


# =====================================================================
# PPTX
# =====================================================================

def novo_deck(usar_template=True):
    """Presentation 16:9 (13.333 x 7.5in) com a marca.

    Com `template-base.pptx` presente, herda fundo texturizado + faixas do
    rodape do slideMaster real. Sem ele, cai no modo fallback.
    """
    from pptx import Presentation
    tpl = template_disponivel() if usar_template else None
    if tpl:
        prs = Presentation(tpl)
        # o template pode trazer slides (caso alguem use o original inteiro):
        # remove todos, ficando so master + layouts.
        _remove_todos_slides(prs)
        prs._hpe_template = True
    else:
        prs = Presentation()
        prs._hpe_template = False
    # 16:9 exato, nos mesmos EMU do arquivo original (13.333 x 7.5 in).
    # Nao usar Inches(13.333): arredonda para 12191695 e quebra o 16:9.
    prs.slide_width = EMU_LARGURA
    prs.slide_height = EMU_ALTURA
    return prs


def _remove_todos_slides(prs):
    xml_slides = prs.slides._sldIdLst
    for sld in list(xml_slides):
        rId = sld.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        try:
            prs.part.drop_rel(rId)
        except Exception:
            pass
        xml_slides.remove(sld)


def _layout_branco(prs):
    """Layout em branco (type=blank) se existir; senao o ultimo/menos populado."""
    for lay in prs.slide_layouts:
        try:
            if lay.element.get("type") == "blank" or "branco" in lay.name.lower() \
                    or "blank" in lay.name.lower():
                return lay
        except Exception:
            pass
    return prs.slide_layouts[6] if len(prs.slide_layouts) > 6 else prs.slide_layouts[-1]


def _limpa_placeholders(slide):
    """Remove placeholders vazios herdados do layout (aparecem como 'Clique...')."""
    for ph in list(slide.placeholders):
        try:
            if not ph.has_text_frame or not ph.text_frame.text.strip():
                ph._element.getparent().remove(ph._element)
        except Exception:
            pass


def aplicar_marca(slide, prs, logo=True, fundo=None, faixa=None):
    """Aplica a marca a QUALQUER slide. Idempotente.

    Este e o primitivo: monte o slide como quiser e chame isso no fim.
    No modo template o fundo e as faixas ja vem do master, entao aqui so
    entra o badge HPE IA. No modo fallback desenha fundo + bolinhas.
    """
    usa_tpl = getattr(prs, "_hpe_template", False)
    if fundo is None:
        fundo = not usa_tpl
    if faixa is None:
        faixa = not usa_tpl

    nomes = {s.name for s in slide.shapes}

    if fundo:
        try:
            slide.background.fill.solid()
            slide.background.fill.fore_color.rgb = _rgb(FUNDO_SOLIDO)
        except Exception:
            pass

    if faixa and "hpe_bolinhas" not in nomes:
        _desenha_bolinhas(slide)

    if logo and "hpe_logo" not in nomes:
        arq = _logo_arquivo()
        if arq:
            try:
                e, t, w, h = GEO["logo"]
                pic = slide.shapes.add_picture(arq, _in(e), _in(t), _in(w), _in(h))
                pic.name = "hpe_logo"
            except Exception:
                pass    # logo ausente/corrompido nunca derruba o deck
    return slide


def _desenha_bolinhas(slide, esq=0.7, topo=6.95, d=0.26, vao=0.13):
    """As 5 bolinhas da marca, desenhadas (modo fallback)."""
    from pptx.enum.shapes import MSO_SHAPE
    grupo = []
    for i, cor in enumerate(PALETA):
        sh = slide.shapes.add_shape(
            MSO_SHAPE.OVAL, _in(esq + i * (d + vao)), _in(topo), _in(d), _in(d))
        sh.name = "hpe_bolinhas" if i == 0 else "hpe_bolinha%d" % i
        sh.fill.solid()
        sh.fill.fore_color.rgb = _rgb(cor)
        sh.line.fill.background()
        sh.shadow.inherit = False
        grupo.append(sh)
    return grupo


def slide_livre(prs):
    """Slide em branco COM a marca. Use para layouts proprios."""
    slide = prs.slides.add_slide(_layout_branco(prs))
    _limpa_placeholders(slide)
    return aplicar_marca(slide, prs)


def caixa_texto(slide, texto, esq, topo, larg, alt, tamanho=None, cor=None,
                negrito=False, alinhamento="esquerda", fonte=None, espaco=1.1,
                ancora="topo"):
    """Caixa de texto na tipografia da marca. `texto` pode ser str ou lista."""
    from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
    from pptx.util import Pt

    ALIN = {"esquerda": PP_ALIGN.LEFT, "centro": PP_ALIGN.CENTER,
            "direita": PP_ALIGN.RIGHT, "justificado": PP_ALIGN.JUSTIFY}
    ANC = {"topo": MSO_ANCHOR.TOP, "meio": MSO_ANCHOR.MIDDLE,
           "base": MSO_ANCHOR.BOTTOM}
    box = slide.shapes.add_textbox(_in(esq), _in(topo), _in(larg), _in(alt))
    tf = box.text_frame
    tf.word_wrap = True
    tf.vertical_anchor = ANC.get(ancora, MSO_ANCHOR.TOP)
    linhas = texto if isinstance(texto, (list, tuple)) else [texto]
    for i, linha in enumerate(linhas):
        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
        p.alignment = ALIN.get(alinhamento, PP_ALIGN.LEFT)
        p.line_spacing = espaco
        r = p.add_run()
        r.text = str(linha)
        r.font.size = Pt(tamanho or PT_CORPO)
        r.font.bold = negrito
        r.font.name = fonte or FONTE
        r.font.color.rgb = _rgb(cor or GRAFITE)
    return box


def _header(slide, titulo, subtitulo=None):
    """O header azul do slide de conteudo, na posicao exata do deck real."""
    e, t, w, h = GEO["titulo"]
    box = caixa_texto(slide, titulo, e, t, w, h, tamanho=PT_TITULO, cor=AZUL,
                      negrito=True, fonte=FONTE_TITULO)
    if subtitulo:
        e2, t2, w2, h2 = GEO["subtitulo"]
        caixa_texto(slide, subtitulo, e2, t2, w2, h2, tamanho=14, cor=CINZA)
    return box


def slide_capa(prs, titulo, subtitulo=None):
    """Capa, com o titulo na posicao/tamanho do slide 1 original (45pt)."""
    slide = slide_livre(prs)
    e, t, w, h = GEO["capa"]
    caixa_texto(slide, titulo, e, t, w, h, tamanho=PT_CAPA, cor=AZUL,
                negrito=True, fonte=FONTE_TITULO)
    if subtitulo:
        caixa_texto(slide, subtitulo, e, t + h + 0.12, w, 0.6,
                    tamanho=PT_CORPO, cor=CINZA)
    return slide


# alias: o nome antigo continua funcionando
slide_titulo = slide_capa


def slide_secao(prs, titulo, numero=None):
    """Divisor de secao. O numero usa a cor da bolinha correspondente."""
    slide = slide_livre(prs)
    y = 2.9
    if numero is not None:
        cor = PALETA[(int(str(numero).strip("0") or 1) - 1) % len(PALETA)] \
            if str(numero).strip("0").isdigit() else PALETA[0]
        caixa_texto(slide, str(numero), 0.9, y - 1.1, 3.0, 1.2,
                    tamanho=PT_DESTAQUE, cor=cor, negrito=True,
                    fonte=FONTE_TITULO)
    caixa_texto(slide, titulo, 0.9, y, 11.0, 1.2, tamanho=34, cor=AZUL,
                negrito=True, fonte=FONTE_TITULO)
    return slide


def slide_conteudo(prs, titulo, bullets, subtitulo=None, tamanho=None):
    """Header + bullets. `bullets` aceita str ou (texto, nivel)."""
    from pptx.enum.text import PP_ALIGN
    from pptx.util import Pt
    tamanho = tamanho or PT_CORPO
    slide = slide_livre(prs)
    _header(slide, titulo, subtitulo)

    e, t, w, h = GEO["corpo"]
    if subtitulo:
        t += 0.25
        h -= 0.25
    box = slide.shapes.add_textbox(_in(e), _in(t), _in(w), _in(h))
    tf = box.text_frame
    tf.word_wrap = True
    itens = bullets if isinstance(bullets, (list, tuple)) else [bullets]
    for i, item in enumerate(itens):
        texto, nivel = item if isinstance(item, (tuple, list)) else (item, 0)
        nivel = min(int(nivel), 4)
        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
        p.level = nivel
        p.alignment = PP_ALIGN.LEFT
        p.space_after = Pt(10)
        r = p.add_run()
        r.text = ("●  " if nivel == 0 else "–  ") + str(texto)
        r.font.size = Pt(tamanho - 3 * nivel)
        r.font.name = FONTE
        r.font.color.rgb = _rgb(GRAFITE if nivel == 0 else CINZA)
    return slide


def slide_grafico(prs, titulo, fig_ou_df, nota=None, kind=None, subtitulo=None):
    """Header + grafico. Aceita figura matplotlib, DataFrame/Series ou caminho png.

    O grafico e salvo com fundo transparente, entao a textura do slide aparece
    atras dele.
    """
    slide = slide_livre(prs)
    _header(slide, titulo, subtitulo)

    if isinstance(fig_ou_df, str):
        png = fig_ou_df
    elif hasattr(fig_ou_df, "savefig"):
        png = _fig_para_png(fig_ou_df)
    elif hasattr(fig_ou_df, "plot"):
        png = _fig_para_png(_df_para_fig(fig_ou_df, kind))
    else:
        raise TypeError(
            "fig_ou_df deve ser figura matplotlib, DataFrame/Series ou caminho png")

    e, t, w, h = GEO["corpo"]
    if subtitulo:
        t += 0.25
        h -= 0.25
    if nota:
        h -= 0.45
    from PIL import Image
    with Image.open(png) as im:
        pw, ph = im.size
    esc = min(w / (pw / 96.0), h / (ph / 96.0))
    lw, lh = (pw / 96.0) * esc, (ph / 96.0) * esc
    slide.shapes.add_picture(png, _in(e + (w - lw) / 2), _in(t + (h - lh) / 2),
                             width=_in(lw), height=_in(lh))
    if nota:
        caixa_texto(slide, nota, e, GEO["rodape_y"] - 0.42, w, 0.4,
                    tamanho=11, cor=CINZA)
    return slide


def card(slide, esq, topo, larg, alt, rotulo=None, valor=None, descricao=None,
         cor=None, texto_cor=None):
    """Bloco colorido (KPI / destaque). Componente pronto que so muda de cor."""
    from pptx.enum.shapes import MSO_SHAPE
    cor = cor or PALETA[0]
    texto_cor = texto_cor or BRANCO
    sh = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE,
                                _in(esq), _in(topo), _in(larg), _in(alt))
    try:
        sh.adjustments[0] = 0.09
    except Exception:
        pass
    sh.fill.solid()
    sh.fill.fore_color.rgb = _rgb(cor)
    sh.line.fill.background()
    sh.shadow.inherit = False
    y = topo + 0.20
    if rotulo:
        caixa_texto(slide, rotulo, esq + 0.22, y, larg - 0.44, 0.32,
                    tamanho=12, cor=texto_cor, negrito=True)
        y += 0.36
    if valor is not None:
        caixa_texto(slide, valor, esq + 0.22, y, larg - 0.44, 0.72,
                    tamanho=30, cor=texto_cor, negrito=True, fonte=FONTE_TITULO)
        y += 0.78
    if descricao:
        caixa_texto(slide, descricao, esq + 0.22, y, larg - 0.44,
                    max(alt - (y - topo) - 0.12, 0.25),
                    tamanho=11, cor=texto_cor)
    return sh


def slide_cards(prs, titulo, cards, subtitulo=None, altura=2.0):
    """Header + linha de cards, coloridos com as bolinhas da marca.

    `cards`: dicts com rotulo/valor/descricao/cor, ou tuplas
    (rotulo, valor) / (rotulo, valor, descricao).
    """
    slide = slide_livre(prs)
    _header(slide, titulo, subtitulo)
    e, t, w, _h = GEO["corpo"]
    if subtitulo:
        t += 0.25

    n = max(len(cards), 1)
    vao = 0.28
    larg = (w - vao * (n - 1)) / n
    for i, c in enumerate(cards):
        if not isinstance(c, dict):
            c = list(c) + [None] * (3 - len(c))
            c = {"rotulo": c[0], "valor": c[1], "descricao": c[2]}
        card(slide, e + i * (larg + vao), t, larg, altura,
             rotulo=c.get("rotulo"), valor=c.get("valor"),
             descricao=c.get("descricao"),
             cor=c.get("cor") or PALETA[i % len(PALETA)])
    return slide


def slide_tabela(prs, titulo, dados, subtitulo=None):
    """Header + tabela zebrada. `dados`: DataFrame ou lista de listas."""
    from pptx.util import Pt
    slide = slide_livre(prs)
    _header(slide, titulo, subtitulo)

    if hasattr(dados, "columns"):
        linhas = [list(map(str, dados.columns))] + dados.astype(str).values.tolist()
    else:
        linhas = [[str(c) for c in r] for r in dados]
    nr, nc = len(linhas), len(linhas[0])
    e, t, w, h = GEO["corpo"]
    if subtitulo:
        t += 0.25
        h -= 0.25
    alt = min(0.38 * nr + 0.1, h)
    tbl = slide.shapes.add_table(nr, nc, _in(e), _in(t), _in(w), _in(alt)).table
    for j, valor in enumerate(linhas[0]):
        cel = tbl.cell(0, j)
        cel.text = valor
        cel.fill.solid()
        cel.fill.fore_color.rgb = _rgb(AZUL)
        for p in cel.text_frame.paragraphs:
            for r in p.runs:
                r.font.bold = True
                r.font.size = Pt(12)
                r.font.name = FONTE_TITULO
                r.font.color.rgb = _rgb(BRANCO)
    for i, linha in enumerate(linhas[1:], start=1):
        for j, valor in enumerate(linha):
            cel = tbl.cell(i, j)
            cel.text = valor
            cel.fill.solid()
            cel.fill.fore_color.rgb = _rgb(BRANCO if i % 2 else "#EDEFF1")
            for p in cel.text_frame.paragraphs:
                for r in p.runs:
                    r.font.size = Pt(11)
                    r.font.name = FONTE
                    r.font.color.rgb = _rgb(GRAFITE)
    return slide


def salvar(prs, nome="apresentacao.pptx"):
    """Salva em /mnt/data e devolve o caminho."""
    path = nome if os.path.isabs(nome) else os.path.join("/mnt/data", nome)
    prs.save(path)
    return path


