# EXCEL (openpyxl)
# =====================================================================

def nova_planilha(aba="Dados", titulo=None):
    """Workbook + worksheet com a marca. Devolve (wb, ws)."""
    from openpyxl import Workbook
    from openpyxl.styles import Font
    wb = Workbook()
    ws = wb.active
    ws.title = str(aba)[:31]
    ws.sheet_properties.tabColor = AZUL.lstrip("#")
    if titulo:
        ws["A1"] = titulo
        ws["A1"].font = Font(name=FONTE_TITULO, size=16, bold=True,
                             color=AZUL.lstrip("#"))
        ws.row_dimensions[1].height = 26
        ws._hpe_inicio = 3
    else:
        ws._hpe_inicio = 1
    return wb, ws


def escrever_tabela(ws, dados, linha_inicial=None, coluna_inicial=1,
                    zebra=True, largura_max=48, formato_numero=None):
    """DataFrame ou lista de listas com cabecalho da marca, zebra, freeze e
    autofiltro. Devolve o numero da ultima linha escrita."""
    from openpyxl.styles import Alignment, Border, Font, PatternFill, Side

    r0 = linha_inicial or getattr(ws, "_hpe_inicio", 1)
    if hasattr(dados, "columns"):
        header = list(map(str, dados.columns))
        corpo = dados.values.tolist()
    else:
        dados = [list(r) for r in dados]
        header, corpo = [str(c) for c in dados[0]], dados[1:]

    fill_h = PatternFill("solid", fgColor=AZUL.lstrip("#"))
    fill_z = PatternFill("solid", fgColor="EDEFF1")
    borda = Border(bottom=Side(style="thin", color="D8DCDF"))

    for j, val in enumerate(header):
        c = ws.cell(row=r0, column=coluna_inicial + j, value=val)
        c.fill = fill_h
        c.font = Font(name=FONTE_TITULO, bold=True, color="FFFFFF", size=11)
        c.alignment = Alignment(horizontal="center", vertical="center",
                               wrap_text=True)
    ws.row_dimensions[r0].height = 22

    for i, linha in enumerate(corpo, start=1):
        for j, val in enumerate(linha):
            c = ws.cell(row=r0 + i, column=coluna_inicial + j, value=val)
            c.font = Font(name=FONTE, size=10, color=GRAFITE.lstrip("#"))
            c.border = borda
            if zebra and i % 2 == 0:
                c.fill = fill_z
            if formato_numero and isinstance(val, (int, float)) \
                    and not isinstance(val, bool):
                c.number_format = formato_numero

    for j, val in enumerate(header):
        col = ws.cell(row=r0, column=coluna_inicial + j).column_letter
        larguras = [len(str(val))] + [len(str(l[j])) for l in corpo if j < len(l)]
        ws.column_dimensions[col].width = min(max(max(larguras) + 4, 10), largura_max)

    ws.freeze_panes = ws.cell(row=r0 + 1, column=coluna_inicial)
    ws.auto_filter.ref = (
        "%s:%s" % (ws.cell(row=r0, column=coluna_inicial).coordinate,
                   ws.cell(row=r0 + len(corpo),
                           column=coluna_inicial + len(header) - 1).coordinate))
    ws._hpe_inicio = r0 + len(corpo) + 3
    return r0 + len(corpo)


def salvar_planilha(wb, nome="planilha.xlsx"):
    path = nome if os.path.isabs(nome) else os.path.join("/mnt/data", nome)
    wb.save(path)
    return path


