def novo_documento(titulo=None, subtitulo=None):
    """Document A4 com tipografia/cores da marca e o badge HPE IA no topo."""
    from docx import Document
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.shared import Cm, Pt, RGBColor

    doc = Document()
    sec = doc.sections[0]
    sec.top_margin = sec.bottom_margin = Cm(2)
    sec.left_margin = sec.right_margin = Cm(2.2)

    normal = doc.styles["Normal"]
    normal.font.name = FONTE
    normal.font.size = Pt(11)
    normal.font.color.rgb = RGBColor.from_string(GRAFITE.lstrip("#"))

    arq = _logo_arquivo()
    if arq:
        try:
            p = doc.add_paragraph()
            p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
            p.add_run().add_picture(arq, height=Cm(1.0))
        except Exception:
            pass
    if titulo:
        h = doc.add_heading(titulo, level=0)
        for r in h.runs:
            r.font.name = FONTE_TITULO
            r.font.color.rgb = RGBColor.from_string(AZUL.lstrip("#"))
    if subtitulo:
        p = doc.add_paragraph(subtitulo)
        for r in p.runs:
            r.font.size = Pt(13)
            r.font.color.rgb = RGBColor.from_string(CINZA.lstrip("#"))
    return doc


def salvar_documento(doc, nome="documento.docx"):
    path = nome if os.path.isabs(nome) else os.path.join("/mnt/data", nome)
    doc.save(path)
    return path


